  4524  /*
  4525   * Reads a CRAM file definition structure.
  4526   * Returns file_def ptr on success
  4527   *         NULL on failure
  4528   */
  4529  cram_file_def *cram_read_file_def(cram_fd *fd) {
  4530      cram_file_def *def = malloc(sizeof(*def));
  4531      if (!def)
  4532          return NULL;
  4533
  4534      if (26 != hread(fd->fp, &def->magic[0], 26)) {
  4535          free(def);
  4536          return NULL;
  4537      }
  4538
  4539      if (memcmp(def->magic, "CRAM", 4) != 0) {
  4540          free(def);
  4541          return NULL;
  4542      }
  4543
  4544      if (def->major_version > 4) {
  4545          hts_log_error("CRAM version number mismatch. Expected 1.x, 2.x, 3.x or 4.x, got %d.%d",
  4546                        def->major_version, def->minor_version);
  4547          free(def);
  4548          return NULL;
  4549      }
  4550
  4551      fd->first_container += 26;
  4552      fd->curr_position = fd->first_container;
  4553      fd->last_slice = 0;
  4554
  4555      return def;
  4556  }
